nonterms = ['E','Ep','T','Tp','F']
terms = ['id','+','*','(',')','$']
first = {'E': {'id','('}, 'Ep': {'+','eps'}, 'T': {'id','('}, 'Tp': {'*','eps'}, 'F': {'id','('}}
follow = {'E': {'$',')'}, 'Ep': {'$',')'}, 'T': {'+','$',')'}, 'Tp': {'+','$',')'}, 'F': {'+','*','$',')'}}
prods = [
 ('E', ('T','Ep'), 'E -> T Ep'),
 ('Ep', ('+','T','Ep'), 'Ep -> + T Ep'),
 ('Ep', (), 'Ep -> epsilon'),
 ('T', ('F','Tp'), 'T -> F Tp'),
 ('Tp', ('*','F','Tp'), 'Tp -> * F Tp'),
 ('Tp', (), 'Tp -> epsilon'),
 ('F', ('id',), 'F -> id'),
 ('F', ('(', 'E', ')'), 'F -> ( E )')
]
def first_seq(seq):
    res = set()
    nullable = True
    for X in seq:
        if X in terms:
            res.add(X)
            nullable = False
            break
        else:
            res |= (first[X] - {'eps'})
            if 'eps' not in first[X]:
                nullable = False
                break
    if nullable:
        res.add('eps')
    return res
M = {}
conflicts = 0
for A, rhs, name in prods:
    fs = first_seq(rhs)
    for a in fs - {'eps'}:
        key = (A, a)
        if key in M and M[key] != name:
            conflicts += 1
        M[key] = name
    if 'eps' in fs:
        for b in follow[A]:
            key = (A, b)
            if key in M and M[key] != name:
                conflicts += 1
            M[key] = name
print(len(M))
print(conflicts)
